import { composeServices } from '@theguild/federation-composition';
import { parse as parseGraphql } from 'graphql';
import { parse, stringify } from 'yaml';
import type { ResolvedSubgraph } from './render.ts';

export const SUPERGRAPH_HEADER_TEXT =
  'generated by `ortzi app supergraph` from every subgraph resource; edit app.yaml or the base config instead';

export interface Composed {
  supergraph: string;
  schema: string;
  router: string;
}

export function compose(
  subgraphs: ResolvedSubgraph[],
  sdls: Record<string, string>,
  base: string,
): Composed {
  const result = composeServices(
    subgraphs.map((subgraph) => ({
      name: subgraph.name,
      url: subgraph.url,
      typeDefs: parseGraphql(sdls[subgraph.name] as string),
    })),
  );

  if (result.errors) {
    throw new Error(
      `supergraph composition failed:\n${result.errors.map((e) => `  ${e.message}`).join('\n')}`,
    );
  }

  return {
    supergraph: `# ${SUPERGRAPH_HEADER_TEXT}\n${result.supergraphSdl.trimEnd()}\n`,
    schema: `# ${SUPERGRAPH_HEADER_TEXT}\n${result.publicSdl.trimEnd()}\n`,
    router: routerConfig(subgraphs, base),
  };
}

export function routerConfig(subgraphs: ResolvedSubgraph[], base: string): string {
  const config = (parse(base) ?? {}) as Record<string, any>;
  const websockets = subgraphs.filter((subgraph) => subgraph.websocket);

  if (websockets.length) {
    config.subscriptions = {
      enabled: true,
      ...config.subscriptions,
      websocket: {
        ...config.subscriptions?.websocket,
        subgraphs: {
          ...config.subscriptions?.websocket?.subgraphs,
          ...Object.fromEntries(
            websockets.map((subgraph) => [subgraph.name, { path: subgraph.websocket }]),
          ),
        },
      },
    };
  }

  return `# ${SUPERGRAPH_HEADER_TEXT}\n${stringify(config, { lineWidth: 0 })}`;
}
